## ----validation_1, include = TRUE, echo = TRUE, warning = FALSE----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
set.seed(1)

N <- 256
t <- (0:(N - 1)) / N

dictionary <- cbind(
  sin(2 * pi * 3  * t),  cos(2 * pi * 3  * t),  sin(2 * pi * 7  * t),
  cos(2 * pi * 7  * t),  sin(2 * pi * 12 * t),  cos(2 * pi * 12 * t),
  sin(2 * pi * 20 * t),  cos(2 * pi * 20 * t)
)

# Unit-L2 normalization of dictionary atoms.
dictionary <- sweep(dictionary, 2, sqrt(colSums(dictionary^2)), "/")

colnames(dictionary) <- c(
  "sin_3", "cos_3",  "sin_7", "cos_7",  
  "sin_12", "cos_12",  "sin_20", "cos_20"
)

## ----validation_2, include = TRUE, echo = TRUE, warning = FALSE----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
true_coef <- c(0, 1.5, 0, 0, -0.8, 0, 0, 0.5)
true_atoms <- c("cos_3", "sin_12", "cos_20")

signal <- as.vector(dictionary %*% true_coef)

## ----validation_3, include = TRUE, echo = TRUE, warning = FALSE----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
out <- omp_core(
  dictionary = dictionary,
  signal = signal,
  n_nonzero_coefs = 3
)

colnames(out$selected_atoms)

out$coefs

## ----validation_4, include = TRUE, echo = TRUE, warning = FALSE----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
setequal(colnames(out$selected_atoms), true_atoms)

relative_error <- sqrt(sum((signal - out$reconstruction)^2)) / sqrt(sum(signal^2))
relative_error

## ----validation_5, include = TRUE, echo = TRUE, warning = FALSE----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
signal_noisy <- signal + rnorm(N, sd = 0.1)

out_noisy <- omp_core(
  dictionary = dictionary,
  signal = signal_noisy,
  n_nonzero_coefs = 3
)

colnames(out_noisy$selected_atoms)

out_noisy$coefs

setequal(colnames(out_noisy$selected_atoms), true_atoms)

## ----validation_6, include = TRUE, echo = TRUE, warning = FALSE----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
relative_residual_error <- sqrt(
  sum((signal_noisy - out_noisy$reconstruction)^2)
  ) / sqrt(sum(signal_noisy^2))

relative_residual_error

relative_clean_error <- sqrt(
  sum((signal - out_noisy$reconstruction)^2)
  ) / sqrt(sum(signal^2))

relative_clean_error

